const source1 = $['Source 1'].first().json;
const source2 = $['Source 2'].first().json;

// Convert hourly arrays from Source 1 into records
const particulateRecords = source1.hourly.time.map((time, i) => ({
  time,
  pm10: source1.hourly.pm10[i],
  pm2_5: source1.hourly.pm2_5[i]
}));

// Convert hourly arrays from Source 2 into records
const gasRecords = source2.hourly.time.map((time, i) => ({
  time,
  nitrogen_dioxide: source2.hourly.nitrogen_dioxide[i],
  ozone: source2.hourly.ozone[i]
}));

// Inner join on exact time values using Set intersection for efficiency
const particulateTimes = new Set(particulateRecords.map(r => r.time));
const gasTimes = new Set(gasRecords.map(r => r.time));
const commonTimes = [...particulateTimes].filter(t => gasTimes.has(t));

// Filter records that exist in both sources
const matchedParticulates = particulateRecords.filter(r => commonTimes.includes(r.time));
const matchedGases = gasRecords.filter(r => commonTimes.includes(r.time));

// Merge matching records preserving all required fields
const mergedRecords = matchedParticulates.map(p => {
  const gas = matchedGases.find(g => g.time === p.time);
  if (gas) {
    return {
      time: p.time,
      pm10: p.pm10,
      pm2_5: p.pm2_5,
      nitrogen_dioxide: gas.nitrogen_dioxide,
      ozone: gas.ozone
    };
  }
});

return [{ json: { records: mergedRecords } }];
